class Solution:
    def bestRotation(self, nums: list[int]) -> int:
        n = len(nums)
        diff = [0] * n
        for i, val in enumerate(nums):
            low = (i + 1) % n
            high = (i - val + n + 1) % n
            diff[low] += 1
            diff[high] -= 1
            if low >= high:
                diff[0] += 1
        best_k = 0
        max_score = -1
        curr = 0
        for k in range(n):
            curr += diff[k]
            if curr > max_score:
                max_score = curr
                best_k = k
        return best_k

class Solution {
public:
    int bestRotation(vector<int>& nums) {
        int n = nums.size();
        vector<int> diff(n, 0);
        for (int i = 0; i < n; ++i) {
            int low = (i + 1) % n;
            int high = (i - nums[i] + n + 1) % n;
            diff[low]++;
            diff[high]--;
            if (low >= high) diff[0]++;
        }
        int best_k = 0, max_score = -1, curr = 0;
        for (int k = 0; k < n; ++k) {
            curr += diff[k];
            if (curr > max_score) {
                max_score = curr;
                best_k = k;
            }
        }
        return best_k;
    }
};

